 'use client';import{useEffect,useState}from'react';import{api}from'../../lib/api';const money=(n:number)=>`₦${Math.round(n/100).toLocaleString('en-NG')}`;export default function Customers(){const[a,setA]=useState<any[]>([]),[q,setQ]=useState(''),[s,setS]=useState(''),[e,setE]=useState('');async function load(){try{const p=new URLSearchParams();if(q)p.set('search',q);if(s)p.set('status',s);setA((await api(`/api/vendor/customers?${p}`)).items||[])}catch(x:any){setE(x.message)}}useEffect(()=>{load()},[s]);return <main className="shell"><div className="page-heading-row"><div><div className="eyebrow">CUSTOMER RELATIONSHIPS</div><h1>Customers</h1><p className="muted">Customers who have ordered from your store.</p></div></div>{e&&<div className="error">{e}</div>}<section className="content-card"><div className="toolbar"><input className="input search-input" value={q} onChange={x=>setQ(x.target.value)} onKeyDown={x=>x.key==='Enter'&&load()} placeholder="Search name, email or phone…"/><select className="input filter-select" value={s} onChange={x=>setS(x.target.value)}><option value="">All activity</option><option value="delivered">Delivered</option><option value="cancelled">Cancelled</option></select></div>{a.length?<div className="customer-table"><div className="customer-head"><span>CUSTOMER</span><span>ORDERS</span><span>SPENT</span><span>LAST ORDER</span></div>{a.map(c=><div className="customer-row" key={c.id}><div><strong>{c.fullName}</strong><small>{c.email||c.phone||'No contact saved'}</small></div><span>{c.orderCount}</span><strong>{money(c.totalSpent)}</strong><span>{new Date(c.lastOrderAt).toLocaleDateString('en-NG')}</span></div>)}</div>:<div className="empty-state"><strong>No customers found</strong><span>Customers appear after they order from your store.</span></div>}</section></main>}